INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(c.id,7),c.id,
 CASE WHEN c.id LIKE 'claim.v0190.voluspa_%' THEN 'source.norse.poetic_edda.gks2365'
      WHEN c.id LIKE 'claim.v0190.gylf_%' THEN 'source.norse.gylfaginning.vsnr2005'
      WHEN c.id IN ('claim.v0190.manuscript_variance') THEN 'source.norse.uppsala_edda.dg11'
      ELSE 'source.norse.skaldskaparmal.vsnr1998' END,
 CASE WHEN c.id LIKE 'claim.v0190.voluspa_%' THEN 'Völuspá 17–18' WHEN c.id LIKE 'claim.v0190.gylf_%' THEN 'Gylfaginning 8–9' ELSE 'Skáldskaparmál edition and notes' END,
 'MEDIEVAL_TEXT','SUPPORTS',c.confidence,'v0.19 witness-scoped evidence'
FROM claims c WHERE c.id LIKE 'claim.v0190.%';

